use std::collections::HashMap;

fn bump_visits(visits: &mut HashMap<String, u32>, names: &[String]) {
    for name in names {
        let count = visits.get(name).copied().unwrap_or(0);
        visits.insert(name.clone(), count + 1);
        let other = visits.get(name).unwrap();
        visits.insert(name.clone(), other + 1);
    }
}

fn main() {
    let mut visits: HashMap<String, u32> = HashMap::new();
    let names = vec![String::from("alice"), String::from("bob"), String::from("alice")];
    bump_visits(&mut visits, &names);
    let mut entries: Vec<_> = visits.iter().collect();
    entries.sort_by_key(|(k, _)| (*k).clone());
    for (k, v) in entries {
        println!("{}: {}", k, v);
    }
}
